(function(){
COURSE_UNITS.push({"id":"search-maps","num":"18","title":"Build the Giants: Search & Maps","color":"indigo","lessons":[{"id":"how-search-engines-work","title":"Crawl, index, answer: how search works"},{"id":"design-google-maps","title":"Google Maps in three moving parts"},{"id":"how-google-docs-works","title":"Google Docs: one page, many cursors"}]});
COURSE_LESSONS["how-search-engines-work"]={"id":"how-search-engines-work","title":"Crawl, index, answer: how search works","summary":"A search engine is three pipelines — crawlers discover pages by following links, indexing turns them into a database of keywords and other signals, and serving analyses the query, retrieves candidates and ranks them. A companion journey shows the browser, DNS, TCP and rendering work needed just to reach the search box.","minutes":18,"level":"intermediate","goals":[{"text":"Three pipelines","step":0},{"text":"Seeds and the frontier","step":1},{"text":"Building the index","step":3},{"text":"The browser's journey","step":5},{"text":"Query analysis","step":9},{"text":"Retrieval","step":10},{"text":"Ranking","step":11}],"steps":[{"short":"Three jobs","chapter":"setup","title":"A search engine is three pipelines","body":["Ask a search engine a question and the answer seems to arrive in a blink. The first ByteByteGo guide separates that blink into three jobs: crawling, which discovers pages; indexing, which organises what was found; and serving, which turns a query into a ranked list of results.","The second guide steps back even further. Before a query can be typed, a browser has to get the search page onto the screen — a small journey through caches, DNS, a TCP handshake and rendering. Together the two guides describe the whole trip, from finding pages to painting pixels.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a> · <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"insight","text":"Search is three pipelines — discover, organise, answer — wrapped in a browser journey."},"changes":["+ Crawling · indexing · serving","+ Browser → DNS → TCP → render"],"scene":{"entities":[{"k":"web","type":"crowd","x0":-17,"x1":-12,"y0":-6,"y1":6,"label":"web pages","color":"ink"},{"k":"crawl","type":"block","x":-7,"y":0,"label":"crawler","color":"blue"},{"k":"idx","type":"db","x":1,"y":0,"label":"index"},{"k":"serve","type":"block","x":9,"y":0,"label":"search service","color":"violet"},{"k":"user","type":"crowd","x0":14,"x1":17,"y0":-6,"y1":6,"label":"seekers","color":"green"}],"links":[{"from":"web","to":"crawl","label":"links"},{"from":"crawl","to":"idx","label":"extract"},{"from":"idx","to":"serve","label":"query"},{"from":"serve","to":"user","label":"results"}]}},{"short":"Seeds","chapter":"technique","title":"Every crawl starts somewhere","body":["A crawler cannot discover the whole web from nothing, so it begins with a list of known pages — the guide calls these seeds. It downloads them, reads their links, and adds those links to the pages it still has to visit.","That simple loop is the discovery engine: seeds lead to links, links lead to more pages, and the frontier keeps growing. The guide's picture is a sprawling network of interconnected content rather than a tidy directory.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"tip","text":"Crawling is a frontier: visit a page, harvest its links, repeat."},"changes":["+ Seed URLs to begin","+ Follow links outward"],"scene":{"entities":[{"k":"seed","type":"block","x":-13,"y":0,"label":"seed URLs","color":"green"},{"k":"crawler","type":"block","x":-3,"y":0,"label":"crawler","color":"blue"},{"k":"web","type":"crowd","x0":12,"x1":16,"y0":-7,"y1":7,"label":"discovered pages","color":"ink"},{"k":"frontier","type":"db","x":-3,"y":8,"label":"frontier queue"}],"links":[{"from":"seed","to":"crawler","label":"start"},{"from":"crawler","to":"web","label":"download"},{"from":"web","to":"crawler","label":"new links"},{"from":"frontier","to":"crawler","label":"next"}]}},{"short":"Why crawl","chapter":"insight","title":"Discovery is never finished","body":["The web does not sit still. Pages appear, disappear and change their content, so a crawl is a continuing activity rather than a one-time import. A search engine that stopped crawling would slowly drift out of date.","Seen this way, the crawler is the freshness budget of the whole system: how often you revisit pages decides how current the answers can be. Inference: that is why crawl scheduling is a design problem in its own right, not just a downloading detail.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"insight","text":"Crawling sets the ceiling on how fresh the index can ever be."},"changes":["+ Pages change constantly","+ Revisits bound freshness"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The crawl loop","lines":["seed  → discover pages","links → grow the frontier","revisit → keep it current"]}],"links":[]}},{"short":"Indexing","chapter":"technique","title":"Pages become an index","body":["Downloaded pages are not stored as a pile of files waiting to be searched. The guide's second stage analyses each page and organises the findings into a massive database called an index.","What gets pulled out matters: keywords, the content type, how fresh the page is, its language, and other classification signals. These are the attributes that later let the engine decide whether a page belongs anywhere near a given query.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"tip","text":"Indexing writes the answers to 'what is this page about?' before anyone asks."},"changes":["+ Extract keywords and language","+ Record type and freshness"],"scene":{"entities":[{"k":"page","type":"block","x":-13,"y":0,"label":"crawled page","color":"green"},{"k":"ext","type":"block","x":-3,"y":0,"label":"analyser","color":"blue"},{"k":"idx","type":"db","x":10,"y":0,"label":"index"}],"links":[{"from":"page","to":"ext","label":"content"},{"from":"ext","to":"idx","label":"keywords · type · freshness"}]}},{"short":"Lookup shape","chapter":"insight","title":"The index is built for questions","body":["The index is not a copy of the web; it is a structure arranged so a question can be answered quickly. If queries arrive as words, it pays to organise the stored signals around words too, pointing each one back at the pages where it appears.","Inference: that reverse arrangement — term to pages, rather than page to terms — is the natural shape for fast retrieval. The guide does not name the data structure, but the need to match query keywords against indexed content explains why it exists.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"insight","text":"Store the data in the shape of the question you expect to ask."},"changes":["+ Index ≠ archive of pages","+ Organised for fast matching"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"Two ways to arrange it","lines":["page → its words   (what we crawled)","word → its pages   (what we query)","the second one makes lookup cheap"]}],"links":[]}},{"short":"The browser","chapter":"technique","title":"Before the query: the browser's part","body":["The second guide begins at the address bar. You type a site name and the browser checks its own cache first; only on a miss does it go looking for the address. That small check saves a network trip for sites you have visited recently.","From there the chain is orderly: find the address, open a connection, make a request, get a response. The guide walks these as numbered steps, and each one is a prerequisite for the next.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"tip","text":"A cache hit skips everything that follows — the fastest request is the one you never send."},"changes":["+ Address bar → browser cache","+ Cache miss → look up the address"],"scene":{"entities":[{"k":"user","type":"crowd","x0":-17,"x1":-13,"y0":-6,"y1":6,"label":"you","color":"ink"},{"k":"cache","type":"block","x":-8,"y":0,"label":"browser cache","color":"green"},{"k":"dns","type":"block","x":0,"y":0,"label":"DNS lookup","color":"blue"},{"k":"net","type":"block","x":8,"y":0,"label":"TCP + HTTP","color":"violet"},{"k":"site","type":"block","x":15,"y":0,"label":"web server","color":"orange"}],"links":[{"from":"user","to":"cache","label":"type URL"},{"from":"cache","to":"dns","label":"miss"},{"from":"dns","to":"net","label":"IP found"},{"from":"net","to":"site","label":"request"}]}},{"short":"DNS","chapter":"technique","title":"An address book with levels","body":["Finding an IP address is described as looking up a phone number, and the guide shows it as a journey through different kinds of DNS servers. The root servers point toward the right top-level domain, that TLD points toward the authoritative server for the name, and the authoritative server supplies the answer.","No single server knows everything; each level narrows the search. Inference: this division is what lets the system answer questions about billions of names without keeping one enormous table anywhere.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"tip","text":"Root → TLD → authoritative: each level delegates the part it does not know."},"changes":["+ Root, TLD, authoritative","+ Final answer: an IP address"],"scene":{"entities":[{"k":"browser","type":"block","x":-14,"y":0,"label":"browser","color":"blue"},{"k":"root","type":"block","x":-5,"y":7,"label":"root","color":"ink"},{"k":"tld","type":"block","x":-5,"y":-7,"label":"TLD server","color":"ink"},{"k":"auth","type":"block","x":5,"y":0,"label":"authoritative","color":"violet"},{"k":"ip","type":"db","x":14,"y":0,"label":"IP address"}],"links":[{"from":"browser","to":"root","label":"who knows?"},{"from":"root","to":"tld","label":"referral"},{"from":"tld","to":"auth","label":"referral"},{"from":"auth","to":"ip","label":"answer"}]}},{"short":"Handshake","chapter":"technique","title":"Say hello before asking","body":["With an IP address in hand, the browser opens a TCP connection. The guide uses HTTP 1.1 as its example: client and server exchange SYN, SYN-ACK and ACK before either treats the connection as ready.","Only then does the HTTP request go out, and only then does the server answer with the HTML, CSS and JavaScript the page is made of. The handshake is a small ritual that prevents both sides from talking to a connection the other never agreed to.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"tip","text":"TCP handshake first, HTTP request second — the request rides on the connection."},"changes":["+ SYN → SYN-ACK → ACK","+ HTTP request → HTML/CSS/JS"],"scene":{"entities":[{"k":"cl","type":"block","x":-12,"y":0,"label":"browser","color":"blue"},{"k":"hs","type":"panel","x":0,"y":0,"title":"Three-way handshake","lines":["SYN","SYN-ACK","ACK"]},{"k":"sv","type":"block","x":12,"y":0,"label":"server","color":"orange"}],"links":[{"from":"cl","to":"sv","label":"HTTP request"},{"from":"sv","to":"cl","label":"HTML · CSS · JS"}]}},{"short":"Pixels","chapter":"insight","title":"From bytes to a page","body":["The response is not the webpage yet. The guide describes the browser parsing the HTML into a DOM tree and the styles into a CSSOM tree, then executing the JavaScript before the page can be drawn.","Rendering is itself a pipeline: a render tree is built, layout works out where everything goes, and painting fills in the pixels. Only at the end does the page appear on screen — the last step of the guide's journey.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"insight","text":"A response becomes a page only after parse, execute, layout and paint."},"changes":["+ HTML → DOM, CSS → CSSOM","+ Render tree → layout → paint"],"scene":{"entities":[{"k":"bytes","type":"block","x":-13,"y":0,"label":"HTML / CSS / JS","color":"green"},{"k":"dom","type":"block","x":-4,"y":0,"label":"DOM + CSSOM","color":"blue"},{"k":"render","type":"block","x":5,"y":0,"label":"render tree","color":"violet"},{"k":"screen","type":"block","x":14,"y":0,"label":"pixels","color":"orange"}],"links":[{"from":"bytes","to":"dom","label":"parse"},{"from":"dom","to":"render","label":"execute JS"},{"from":"render","to":"screen","label":"layout · paint"}]}},{"short":"Query analysis","chapter":"technique","title":"Now the query: what did you mean?","body":["Back in the search engine proper, the first serving stage is query analysis. The guide lists identifying keywords, recognising synonyms and interpreting context or intent — the engine tries to understand the question before it goes looking.","Two searches with different words can therefore lead to the same place. Inference: expanding a query with synonyms is what lets a search for one phrase find pages that never use those exact words.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"tip","text":"Understand first, retrieve second — analysis turns words into intent."},"changes":["+ Keywords and synonyms","+ Context and intent"],"scene":{"entities":[{"k":"user","type":"crowd","x0":-15,"x1":-12,"y0":-6,"y1":6,"label":"query","color":"ink"},{"k":"ana","type":"block","x":-3,"y":0,"label":"query analysis","color":"blue"},{"k":"term","type":"block","x":12,"y":0,"label":"terms + intent","color":"violet"}],"links":[{"from":"user","to":"ana","label":"question"},{"from":"ana","to":"term","label":"understood"}]}},{"short":"Retrieval","chapter":"technique","title":"Match the index, not the web","body":["With a analysed query in hand, retrieval searches the index for pages whose stored content matches. The guide describes this as matching the query's keywords against the indexed content of web pages.","The crucial point is where this happens: the engine consults the index it built during crawling, not the live web. That is the whole reason the index exists — to make this match fast enough for an interactive answer.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"insight","text":"Retrieval is a lookup against the index, not a fresh crawl of the internet."},"changes":["+ Match keywords to indexed content","+ Produce a candidate set"],"scene":{"entities":[{"k":"idx","type":"db","x":-13,"y":0,"label":"index"},{"k":"match","type":"block","x":-1,"y":0,"label":"matcher","color":"blue"},{"k":"cand","type":"crowd","x0":12,"x1":16,"y0":-7,"y1":7,"label":"candidate pages","color":"green"}],"links":[{"from":"idx","to":"match","label":"lookup"},{"from":"match","to":"cand","label":"candidates"}]}},{"short":"Ranking","chapter":"technique","title":"Order is the product","body":["Retrieval hands over a set of relevant pages; ranking turns that set into an ordered list. The guide says the retrieved pages are ranked by relevance and other factors, after the query has been analysed and matched.","Inference: the signals gathered during indexing — freshness, language, content type — are natural inputs to that ordering, because they were recorded precisely to say something about a page. Relevance is not a single number; it is a judgement assembled from several signals.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"insight","text":"Finding the right pages and ordering them are two different jobs."},"changes":["+ Relevance plus other factors","+ An ordered result list"],"scene":{"entities":[{"k":"cand","type":"crowd","x0":-14,"x1":-11,"y0":-7,"y1":7,"label":"candidates","color":"ink"},{"k":"rank","type":"block","x":-1,"y":0,"label":"ranker","color":"violet"},{"k":"out","type":"crowd","x0":12,"x1":16,"y0":-7,"y1":7,"label":"ranked results","color":"green"}],"links":[{"from":"cand","to":"rank","label":"score"},{"from":"rank","to":"out","label":"ordered"}]}},{"short":"Order matters","chapter":"problem","title":"Page two might as well not exist","body":["There is a sharp edge to ranking. A page that genuinely answers the question but lands at position twenty will almost never be seen, so getting the order right matters more than finding one more barely relevant page.","Inference: that is why the serving stage gets its own place in the guide alongside crawling and indexing. The system is not just about having the information — it is about putting the most helpful answer in front of the person who asked.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"warn","text":"The best answer buried deep in the list is effectively a wrong answer."},"changes":["+ Visibility falls off fast","+ Ranking is user-facing behaviour"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The same good page","lines":["rank 1  → opened, trusted","rank 20 → never clicked","content identical; position decides"]}],"links":[]}},{"short":"Dials","chapter":"tradeoff","title":"Three dials you cannot all maximise","body":["The three stages pull against each other. Crawling more aggressively improves freshness but costs bandwidth and processing; a deeper index covers more pages but makes lookup heavier; richer ranking can be more relevant but slower to compute.","Inference: the guide presents the stages separately, but a real engine has to budget across all three. Search quality is an exercise in choosing where to spend time and storage, not in making every stage perfect.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a>.</span>"],"callout":{"kind":"insight","text":"Freshness, coverage and latency are competing budgets, not free wins."},"changes":["+ Crawl rate ↔ freshness cost","+ Depth ↔ lookup speed","+ Relevance ↔ latency"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The three dials","lines":["freshness  ↔ crawl cost","coverage   ↔ index size","relevance  ↔ answer time"]}],"links":[]}},{"short":"Recap","chapter":"recap","title":"The whole trip, end to end","body":["Two guides, one story. The browser guide carries you from typed address through cache, DNS, a TCP handshake, an HTTP response and rendering until the page appears. The search guide then takes over: crawlers discover pages, indexing organises them into a searchable structure, and serving analyses the query, retrieves candidates and ranks them.","The mental model is a relay: the browser gets you to the search box, discovery and indexing build the thing that can answer, and analysis plus retrieval plus ranking produce the answer you see.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-do-search-engines-work.md\" target=\"_blank\" rel=\"noopener noreferrer\">How Do Search Engines Work?</a> · <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/what-happens-when-you-type-google.md\" target=\"_blank\" rel=\"noopener noreferrer\">What Happens When You Type google.com Into a Browser?</a>.</span>"],"callout":{"kind":"next","text":"Next: <b>the unit review</b> — put search, maps and collaborative editing together."},"changes":["+ Browser: cache → DNS → TCP → render","+ Search: crawl → index → analyse → retrieve → rank"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"One continuous trip","lines":["typed URL → page on screen","crawl → index → query → results","both are pipelines of small ordered steps"]}],"links":[]}}]};
COURSE_LESSONS["design-google-maps"]={"id":"design-google-maps","title":"Google Maps in three moving parts","summary":"A simplified Maps design has three components: a location service that records frequent client pings to improve the map and feed live traffic, a rendering path that serves precomputed static tiles from a CDN, and a navigation service that geocodes addresses, finds top-K shortest paths, estimates travel time and ranks the routes.","minutes":16,"level":"intermediate","goals":[{"text":"Three components","step":0},{"text":"Recording location","step":1},{"text":"The tile model","step":3},{"text":"CDN delivery","step":4},{"text":"Geocoding","step":7},{"text":"Route planning","step":8},{"text":"Ranking routes","step":10}],"steps":[{"short":"Three parts","chapter":"setup","title":"A map with a billion daily users","body":["The Maps guide starts with scale: Google began the project in 2005, and by March 2021 it reported about a billion daily active users and coverage of nearly the whole world. A system that size cannot be one big program — the guide breaks it into three high-level pieces.","Those pieces are a location service that records where clients are, a rendering path that gets map imagery onto the screen, and a navigation service that finds a route. Each has a different rhythm: one is a stream of updates, one is a cache of static images, and one is a request that runs a search.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"Maps is three systems with three different tempos, not one monolith."},"changes":["+ Location service","+ Map rendering","+ Navigation service"],"scene":{"entities":[{"k":"clients","type":"crowd","x0":-17,"x1":-13,"y0":-7,"y1":7,"label":"map clients","color":"green"},{"k":"loc","type":"block","x":-4,"y":7,"label":"location service","color":"blue"},{"k":"render","type":"block","x":-4,"y":-7,"label":"map rendering","color":"violet"},{"k":"nav","type":"block","x":7,"y":0,"label":"navigation","color":"orange"}],"links":[{"from":"clients","to":"loc","label":"pings"},{"from":"clients","to":"render","label":"tiles"},{"from":"clients","to":"nav","label":"route request"}]}},{"short":"Pings","chapter":"technique","title":"Clients report where they are","body":["Map clients send location updates every few seconds, and the location service is responsible for recording them. The guide treats this stream as a first-class input rather than a byproduct of using the app.","A continuous stream of positions from moving devices is what turns a static map into a living one. Inference: at the guide's scale the arrival rate is enormous, so this path has to be cheap per update and able to absorb bursts.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"tip","text":"A location update is a write, not a read — the ping path is a high-volume pipeline."},"changes":["+ Updates every few seconds","+ Recorded by the location service"],"scene":{"entities":[{"k":"phones","type":"crowd","x0":-15,"x1":-12,"y0":-7,"y1":7,"label":"moving clients","color":"green"},{"k":"loc","type":"block","x":-2,"y":0,"label":"location service","color":"blue"},{"k":"store","type":"db","x":13,"y":0,"label":"location data"}],"links":[{"from":"phones","to":"loc","label":"ping"},{"from":"loc","to":"store","label":"record"}]}},{"short":"Why pings","chapter":"insight","title":"What all those positions are for","body":["The guide gives three concrete uses for the collected location data: detecting new roads and roads that have recently closed, improving the accuracy of the map over time, and feeding live traffic information.","That list explains why the app asks for location at all. The same positions improve the base map and power a service that changes minute by minute — a nice example of one data stream serving both slow and fast needs.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"One stream of pings improves the permanent map and the live traffic view."},"changes":["+ Detect new and closed roads","+ Sharpen accuracy","+ Feed live traffic"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"Three uses for a ping","lines":["new & recently closed roads","map accuracy over time","input to live traffic data"]}],"links":[]}},{"short":"Tiles","chapter":"technique","title":"The world as small static pictures","body":["For rendering, the guide describes projecting the world's map into one huge two-dimensional image and then cutting it into small image blocks called tiles. The client loads the tiles it needs and stitches them into the map it shows.","The key property is that tiles are static — they do not change often. That single fact decides how they can be stored and delivered, and it is the reason rendering is treated separately from the fast-moving location stream.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"tip","text":"Cut a huge image into small pieces, then fetch only the pieces on screen."},"changes":["+ 2D projection of the world","+ Static tiles, rarely changed"],"scene":{"entities":[{"k":"world","type":"block","x":-13,"y":0,"label":"world map","color":"green"},{"k":"tiles","type":"block","x":-1,"y":0,"label":"tile blocks","color":"blue"},{"k":"client","type":"crowd","x0":13,"x1":16,"y0":-7,"y1":7,"label":"map view","color":"ink"}],"links":[{"from":"world","to":"tiles","label":"slice up"},{"from":"tiles","to":"client","label":"load nearby"}]}},{"short":"CDN","chapter":"technique","title":"Serve tiles from nearby","body":["Because tiles are static files, the guide recommends an efficient delivery shape: a content delivery network backed by cloud object storage. The storage holds the tiles; the CDN keeps copies close to users.","A client asks for the tiles around its current view and gets them from a nearby CDN node instead of from an origin far away. Inference: this is the same reason any large static catalogue uses a CDN — bytes that never change should never make a long trip.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"tip","text":"Static files belong on a CDN; the origin only serves the cache misses."},"changes":["+ Object storage as origin","+ CDN copies near users"],"scene":{"entities":[{"k":"store","type":"db","x":-13,"y":0,"label":"tile storage"},{"k":"cdn","type":"block","x":-1,"y":0,"label":"CDN","color":"blue"},{"k":"client","type":"crowd","x0":13,"x1":16,"y0":-7,"y1":7,"label":"viewers","color":"green"}],"links":[{"from":"store","to":"cdn","label":"origin"},{"from":"cdn","to":"client","label":"cached tile"}]}},{"short":"Zoom","chapter":"technique","title":"Panning and zooming without recomputing","body":["When a user zooms or pans, the view needs different detail. The guide's answer is to pre-calculate map blocks at different zoom levels and load images as they are needed, rather than working them out on demand.","So zooming is a choice among already-built tile sets: a wide view uses fewer, coarser tiles; a close view uses many fine ones. Inference: trading storage for predictable, fast interaction is a deliberate design choice at this scale.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"Precompute the zoom levels so interaction is only a fetch, never a calculation."},"changes":["+ Tiles precomputed per zoom level","+ Load on demand as the view moves"],"scene":{"entities":[{"k":"user","type":"crowd","x0":-15,"x1":-12,"y0":-6,"y1":6,"label":"zooming user","color":"ink"},{"k":"pyramid","type":"block","x":-2,"y":0,"label":"tile pyramid","color":"violet"},{"k":"levels","type":"db","x":12,"y":0,"label":"zoom levels"}],"links":[{"from":"user","to":"pyramid","label":"zoom / pan"},{"from":"pyramid","to":"levels","label":"pick level"}]}},{"short":"Two clocks","chapter":"insight","title":"Static tiles, moving traffic","body":["Here is the seam in the design. The base imagery is static, cached and precomputed; the traffic derived from those frequent location pings is live. The guide keeps them in different components for exactly this reason.","Inference: merging the two clocks would be wasteful — recomputing the world's tiles every time a car moved is impossible, while showing yesterday's traffic is useless. Letting each layer change at its own pace is what makes both affordable.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"Let the base map change slowly and the live layer change quickly."},"changes":["+ Base map: hours or longer","+ Traffic: minutes or seconds"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"Two clocks","lines":["tiles   → static, cached, precomputed","traffic → live, from location pings","different tempos, different pipelines"]}],"links":[]}},{"short":"Geocoding","chapter":"technique","title":"An address is not a coordinate","body":["Navigation starts with a request to find a reasonably fast route from point A to point B. But people type addresses, while route calculations need positions, so the navigation service first calls a geocoding service that resolves an address to a latitude/longitude pair.","Geocoding is the translation layer between human input and machine geometry. Inference: without it every routing algorithm would have to understand street names, which is exactly the kind of mess a separate service is meant to hide.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"tip","text":"Geocoding turns words into coordinates before routing can begin."},"changes":["+ Address typed by the user","+ Resolved to latitude / longitude"],"scene":{"entities":[{"k":"addr","type":"block","x":-13,"y":0,"label":"address A → B","color":"green"},{"k":"geo","type":"block","x":0,"y":0,"label":"geocoding","color":"blue"},{"k":"coords","type":"db","x":13,"y":0,"label":"lat / long"}],"links":[{"from":"addr","to":"geo","label":"text"},{"from":"geo","to":"coords","label":"coordinates"}]}},{"short":"Paths","chapter":"technique","title":"Find several candidate routes","body":["The route planner does three things in sequence, and the first is to calculate the top-K shortest paths between the two points. It does not commit to a single route immediately; it keeps a small set of alternatives.","Keeping several paths matters because the shortest line on a map is not always the quickest one in the real world. Inference: having candidates is what gives the later ranking stage something to choose between.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"Generate a few good options first; decide which is best later."},"changes":["+ Top-K shortest paths","+ Keep alternatives alive"],"scene":{"entities":[{"k":"start","type":"block","x":-13,"y":0,"label":"A → B coords","color":"green"},{"k":"planner","type":"block","x":-1,"y":0,"label":"route planner","color":"blue"},{"k":"paths","type":"crowd","x0":12,"x1":16,"y0":-7,"y1":7,"label":"top-K paths","color":"violet"}],"links":[{"from":"start","to":"planner","label":"request"},{"from":"planner","to":"paths","label":"candidates"}]}},{"short":"Time","chapter":"technique","title":"Estimate time for each path","body":["The planner's second step is to estimate the time each path will take, using current traffic together with historical data. Distance alone is not enough: a shorter road at a busy hour can lose to a longer one that is moving freely.","This is where the live traffic stream meets the route calculation. The guide pairs the present picture with past patterns, so the estimate reflects both what is happening now and what usually happens on that road at that time.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"tip","text":"Rank by travel time, and build that time from live and historical data."},"changes":["+ Current traffic","+ Historical patterns","+ An ETA per path"],"scene":{"entities":[{"k":"paths","type":"block","x":-13,"y":0,"label":"candidate paths","color":"green"},{"k":"live","type":"db","x":-1,"y":7,"label":"live traffic"},{"k":"hist","type":"db","x":-1,"y":-7,"label":"historical data"},{"k":"etas","type":"crowd","x0":13,"x1":16,"y0":-7,"y1":7,"label":"ETAs","color":"violet"}],"links":[{"from":"paths","to":"etas","label":"estimate"},{"from":"live","to":"etas","label":"now"},{"from":"hist","to":"etas","label":"past"}]}},{"short":"Rank","chapter":"technique","title":"Rank by time and by preference","body":["The planner's third step is to rank the paths using those time predictions and user filtering. The guide's example is a driver who does not want to avoid tolls — a preference that changes which route comes out on top even if another is slightly faster.","So the final answer is not simply 'shortest' or 'fastest'. It is fastest subject to what the person asked for, which is why the ranking step needs both the ETA and the filter.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"The recommended route is fast under the user's own constraints."},"changes":["+ Rank by predicted time","+ Apply user filters such as tolls"],"scene":{"entities":[{"k":"etas","type":"crowd","x0":-14,"x1":-11,"y0":-7,"y1":7,"label":"scored paths","color":"ink"},{"k":"rank","type":"block","x":-1,"y":0,"label":"ranker","color":"violet"},{"k":"best","type":"block","x":12,"y":0,"label":"best route","color":"green"}],"links":[{"from":"etas","to":"rank","label":"time + filters"},{"from":"rank","to":"best","label":"recommended"}]}},{"short":"Scale","chapter":"problem","title":"A billion clients, every few seconds","body":["Put the guide's numbers next to its ping rate and the challenge becomes clear: roughly a billion daily active users, each sending location every few seconds, all feeding one recording path while simultaneously requesting tiles and routes.","Inference: this is why the three components are separated. A single service trying to absorb the write stream, serve static images and run path searches would have no way to scale each part on its own terms.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"warn","text":"Scale is what forces the split — the three pieces have different growth curves."},"changes":["+ ~1B daily users at the guide's 2021 figure","+ Continuous pings plus reads and searches"],"scene":{"entities":[{"k":"phones","type":"crowd","x0":-15,"x1":-12,"y0":-8,"y1":8,"label":"~1B clients","color":"green"},{"k":"loc","type":"block","x":-2,"y":0,"label":"location service","color":"blue"},{"k":"store","type":"db","x":13,"y":0,"label":"huge location store"}],"links":[{"from":"phones","to":"loc","label":"every few sec"},{"from":"loc","to":"store","label":"append"}]}},{"short":"Tradeoffs","chapter":"tradeoff","title":"Detail, freshness and timeliness","body":["The design is full of small bargains. More frequent pings sharpen traffic and the map but cost storage and processing; more zoom levels mean more tiles to precompute and keep; deeper route search can find a better path but takes longer to answer.","Inference: the guide describes what each component does, not how far to push it. Those settings are the knobs an operator turns, and they are chosen against a budget rather than a wish list.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"insight","text":"Every improvement has a bill — the art is choosing which bill to pay."},"changes":["+ Update rate ↔ storage cost","+ Zoom levels ↔ precompute size","+ Search depth ↔ response time"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The knobs","lines":["ping rate   ↔ cost to record","zoom detail ↔ tiles to build","route depth ↔ time to answer"]}],"links":[]}},{"short":"Recap","chapter":"recap","title":"Three parts, one map","body":["The guide's simplified Google Maps has three moving pieces. The location service records the pings clients send every few seconds and uses them to spot road changes, improve accuracy and feed live traffic. Rendering projects the world into static tiles, precomputed at several zoom levels and served from a CDN over object storage. Navigation geocodes the addresses, asks the planner for top-K shortest paths, estimates each one's time from live and historical data, and ranks them under the user's filters.","The mental model: one stream for where everyone is, one cache for what the world looks like, one search for how to get somewhere.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/design-google-maps.md\" target=\"_blank\" rel=\"noopener noreferrer\">Design Google Maps</a>.</span>"],"callout":{"kind":"next","text":"Next: <b>the unit review</b> — put search, maps and collaborative editing together."},"changes":["+ Location → record pings","+ Rendering → cached tiles","+ Navigation → geocode → plan → rank"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The three parts","lines":["location  → record pings","rendering → cached tiles per zoom","navigation → geocode → paths → ETA → rank"]}],"links":[]}}]};
COURSE_LESSONS["how-google-docs-works"]={"id":"how-google-docs-works","title":"Google Docs: one page, many cursors","summary":"Collaborative editing sends operations — not whole files — over a WebSocket, persists them in a message queue, and lets a file operation server transform concurrent edits so every client converges. Three kinds of data are stored: metadata, content and operations, with conflict resolution via OT, differential synchronisation or CRDTs.","minutes":15,"level":"intermediate","goals":[{"text":"The pipeline","step":0},{"text":"Operations, not files","step":1},{"text":"The WebSocket channel","step":2},{"text":"Persist in a queue","step":3},{"text":"The conflict problem","step":5},{"text":"Transform operations","step":6},{"text":"Three stores","step":9}],"steps":[{"short":"One page","chapter":"setup","title":"One document, many cursors","body":["The Docs guide sketches a collaborative editor: several clients editing the same file at once, with everyone seeing a consistent result. Its shape is a short pipeline that turns individual keystrokes into shared, stored document state.","The parts are a WebSocket server for live traffic, a message queue that holds operations, a file operation server that transforms them, and three kinds of stored data. The hard part, the guide says, is real-time conflict resolution when edits collide.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"Collaboration is a pipeline from local keystroke to shared, consistent state."},"changes":["+ WebSocket server","+ Message queue","+ File operation server","+ Three stores"],"scene":{"entities":[{"k":"clients","type":"crowd","x0":-17,"x1":-13,"y0":-7,"y1":7,"label":"editors","color":"green"},{"k":"ws","type":"block","x":-6,"y":0,"label":"WebSocket server","color":"blue"},{"k":"mq","type":"db","x":3,"y":0,"label":"message queue"},{"k":"fos","type":"block","x":13,"y":0,"label":"file op. server","color":"violet"}],"links":[{"from":"clients","to":"ws","label":"edit ops"},{"from":"ws","to":"mq","label":"persist"},{"from":"mq","to":"fos","label":"consume"}]}},{"short":"Operations","chapter":"technique","title":"Send operations, not the whole file","body":["Clients send document editing operations to the WebSocket server. The guide frames the unit of traffic as an operation — a change to make — rather than a copy of the document each time someone types.","Inference: that choice keeps the live channel small. Sending the entire file on every keystroke would waste bandwidth and make it much harder to work out what changed, so the system moves the differences around instead.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"tip","text":"Transmit the change, not the document — the operation is the message."},"changes":["+ Client creates an edit operation","+ Operation goes to the WebSocket server"],"scene":{"entities":[{"k":"editor","type":"crowd","x0":-14,"x1":-11,"y0":-6,"y1":6,"label":"typing client","color":"ink"},{"k":"op","type":"block","x":-3,"y":0,"label":"edit operation","color":"green"},{"k":"ws","type":"block","x":11,"y":0,"label":"WebSocket server","color":"blue"}],"links":[{"from":"editor","to":"op","label":"keystroke"},{"from":"op","to":"ws","label":"send"}]}},{"short":"WebSocket","chapter":"technique","title":"A channel that stays open","body":["The guide states plainly that real-time communication is handled by the WebSocket server. A WebSocket keeps a two-way connection alive, so edits can travel from a client to the server and updates can travel back without opening a new request each time.","That persistent channel is what makes typing feel immediate: the server can push other people's changes to you the moment they arrive, rather than waiting for your browser to ask again.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"Real-time needs a push channel, not a request that waits for a reply."},"changes":["+ Persistent two-way connection","+ Server can broadcast changes"],"scene":{"entities":[{"k":"a","type":"crowd","x0":-15,"x1":-12,"y0":-7,"y1":-1,"label":"Alice","color":"green"},{"k":"ws","type":"block","x":0,"y":0,"label":"WebSocket server","color":"blue"},{"k":"b","type":"crowd","x0":12,"x1":15,"y0":-7,"y1":-1,"label":"Bob","color":"green"}],"links":[{"from":"a","to":"ws","label":"send"},{"from":"ws","to":"b","label":"broadcast"}]}},{"short":"Queue","chapter":"technique","title":"Persist the operations first","body":["Document operations are persisted in a message queue before anything else happens to them. The file operation server then consumes what the clients produced, so the queue sits between receiving an edit and acting on it.","Inference: a queue both survives a restart and gives the consumer a stable, ordered stream to work through. If the transform stage falls behind, operations simply wait their turn instead of being lost.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"tip","text":"Persist first, transform second — the queue makes the two stages independent."},"changes":["+ Operations written to the queue","+ Consumed in order"],"scene":{"entities":[{"k":"ws","type":"block","x":-12,"y":0,"label":"WebSocket server","color":"blue"},{"k":"mq","type":"db","x":0,"y":0,"label":"message queue"},{"k":"fos","type":"block","x":12,"y":0,"label":"file op. server","color":"violet"}],"links":[{"from":"ws","to":"mq","label":"append"},{"from":"mq","to":"fos","label":"consume"}]}},{"short":"Why a queue","chapter":"insight","title":"The buffer buys you room","body":["Separating receive from transform has a useful consequence. Ten people typing at once produce a burst of operations, but the transform stage can keep working at its own pace, drawing from the queue as it catches up.","Inference: this is the ordinary value of a queue — it absorbs bursts and decouples two speeds. In a collaborative editor it also creates a replayable record of what clients sent, which is handy when diagnosing a disagreement between two screens.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"A queue turns a burst of edits into an orderly stream you can process."},"changes":["+ Absorb simultaneous edits","+ Ordered, replayable input"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"What the queue gives you","lines":["bursts in  → steady stream out","order     → predictable transforms","replay    → a record of raw edits"]}],"links":[]}},{"short":"Conflict","chapter":"problem","title":"Two people, the same spot","body":["The guide calls real-time conflict resolution one of the biggest challenges. If Alice inserts text at a position while Bob deletes near that same position, applying both edits naively can lose one of them or leave the two clients showing different documents.","The problem is not the network — both edits arrived. It is that each was written assuming a document that the other has already changed. Something has to reconcile those assumptions before the result is shared.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"warn","text":"Both edits are valid on their own; the trouble starts when they overlap."},"changes":["+ Simultaneous edits to one region","+ Naive application diverges"],"scene":{"entities":[{"k":"alice","type":"block","x":-13,"y":-6,"label":"Alice: insert at 10","color":"orange"},{"k":"bob","type":"block","x":-13,"y":6,"label":"Bob: delete at 10","color":"red"},{"k":"clash","type":"block","x":10,"y":0,"label":"same position","color":"red"}],"links":[{"from":"alice","to":"clash","label":"edit"},{"from":"bob","to":"clash","label":"edit"}]}},{"short":"Transform","chapter":"technique","title":"Produce transformed operations","body":["The file operation server consumes the operations produced by clients and generates transformed operations using collaboration algorithms. The raw edits come in; adjusted edits that account for one another go out.","This is the step that resolves the collision from the previous scene. Inference: the transformation runs centrally so every client receives the same reconciled stream, which is how the document converges instead of drifting apart.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"Transform before broadcasting, so everyone receives the same edits."},"changes":["+ Consume raw client operations","+ Emit transformed operations"],"scene":{"entities":[{"k":"mq","type":"db","x":-13,"y":0,"label":"raw operations"},{"k":"fos","type":"block","x":-1,"y":0,"label":"file op. server","color":"violet"},{"k":"out","type":"crowd","x0":13,"x1":16,"y0":-7,"y1":7,"label":"transformed ops","color":"green"}],"links":[{"from":"mq","to":"fos","label":"consume"},{"from":"fos","to":"out","label":"collaboration algorithms"}]}},{"short":"Algorithms","chapter":"insight","title":"Three families of conflict resolution","body":["The guide names three common approaches. Operational transformation — OT — rewrites an incoming edit in light of edits already applied. Differential synchronisation works by comparing versions, and CRDTs are data types designed so concurrent changes combine cleanly.","The guide also notes, citing its Wikipedia page, that Google Docs uses OT, while CRDTs remain an active research area for real-time concurrent editing. Inference: choosing a family is a trade-off between how much bookkeeping the client carries and how hard the merge logic is to get right.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"tip","text":"OT and CRDT solve the same problem from opposite directions."},"changes":["+ Operational transformation","+ Differential synchronisation","+ CRDT"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"Three families","lines":["OT  → transform edits against each other","DS  → compare and reconcile versions","CRDT → data types that merge by design"]}],"links":[]}},{"short":"OT idea","chapter":"technique","title":"Rebase, then converge","body":["To make the idea concrete: imagine both clients start from the same document. Alice's edit is applied first; Bob's edit was written against the older version, so it has to be rebased past Alice's change before it is applied. Done consistently, both clients end up with the same text.","Inference: this is an explanation of the idea behind OT in plain language, not a claim that the guide spells out the algorithm step by step. The guide's point is that some transformation is necessary, and that OT is the family Google Docs is reported to use.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"Convergence means two editors arrive at the same document, whatever the order."},"changes":["+ Apply the first edit","+ Rebase the second","+ Both screens agree"],"scene":{"entities":[{"k":"base","type":"block","x":-13,"y":0,"label":"same starting text","color":"green"},{"k":"a","type":"block","x":-3,"y":-6,"label":"apply Alice","color":"blue"},{"k":"b","type":"block","x":-3,"y":6,"label":"rebase Bob","color":"violet"},{"k":"same","type":"block","x":12,"y":0,"label":"converged","color":"orange"}],"links":[{"from":"base","to":"a","label":"edit 1"},{"from":"base","to":"b","label":"edit 2"},{"from":"a","to":"same","label":"shared result"},{"from":"b","to":"same","label":"shared result"}]}},{"short":"Three stores","chapter":"technique","title":"Three kinds of stored data","body":["The guide is explicit that three types of data are stored: file metadata, file content and operations. They are not the same thing, and mixing them would blur the boundaries of the design.","Metadata describes the file, content is the document as it stands, and operations are the edits that produced it. Keeping the three separate lets each be written and queried in the way that suits it.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"tip","text":"Name, current text and edit history are three different things to store."},"changes":["+ File metadata","+ File content","+ Operations"],"scene":{"entities":[{"k":"fos","type":"block","x":-13,"y":0,"label":"file op. server","color":"violet"},{"k":"meta","type":"db","x":0,"y":-7,"label":"metadata"},{"k":"content","type":"db","x":0,"y":0,"label":"file content"},{"k":"ops","type":"db","x":0,"y":7,"label":"operations"}],"links":[{"from":"fos","to":"meta","label":"describe"},{"from":"fos","to":"content","label":"update"},{"from":"fos","to":"ops","label":"record"}]}},{"short":"Why history","chapter":"insight","title":"The present and the story of it","body":["Current content answers 'what does the document say right now?'. The stored operations answer 'how did it get here?'. Inference: that second question is what lets a colleague who joined late catch up, and what lets a system rebuild or audit a document after a mistake.","Metadata sits alongside both: it is the small descriptive layer — names and ownership — that lets a user find the file in the first place. Three stores, three questions, one document.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"insight","text":"Content is the answer today; operations are the explanation behind it."},"changes":["+ Content → current text","+ Operations → how it changed","+ Metadata → identity"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"Three questions","lines":["content → what is in the file now?","ops     → how did it get this way?","meta    → whose file is it, and what is it called?"]}],"links":[]}},{"short":"Tradeoff","chapter":"tradeoff","title":"Correctness has a price","body":["The guide stops short of prescribing one answer for every editor. It lists the options and notes which one Google Docs reportedly uses, leaving the trade-off visible: a transformation scheme has to be correct for every interleaving of edits, which is notoriously subtle.","Inference: a CRDT can make convergence easier to reason about but carries more metadata, while OT keeps messages compact at the cost of careful, central transformation logic. The design question is what your clients and your team can afford to carry.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"warn","text":"Pick the conflict strategy deliberately — getting it wrong loses someone's work."},"changes":["+ OT: compact edits, hard correctness","+ CRDT: easier merge, more metadata"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The tension","lines":["OT   → small messages, tricky transforms","CRDT → simpler merge, heavier state","both → one consistent document"]}],"links":[]}},{"short":"Recap","chapter":"recap","title":"Everyone sees the same page","body":["Clients send editing operations over a WebSocket connection; the operations are persisted in a message queue and consumed by the file operation server, which generates transformed operations using collaboration algorithms so concurrent edits converge. The system stores three kinds of data — file metadata, file content and the operations themselves — and the guide flags real-time conflict resolution as the central difficulty, naming OT, differential synchronisation and CRDT as the common approaches.","The mental model: send changes, queue them, transform them, store three views, and make sure every screen ends up in the same place.","<span class=\"src\">Grounded in ByteByteGo’s <a href=\"https://github.com/ByteByteGoHq/system-design-101/blob/main/data/guides/how-to-design-google-docs.md\" target=\"_blank\" rel=\"noopener noreferrer\">How to Design Google Docs</a>.</span>"],"callout":{"kind":"next","text":"Next: <b>the unit review</b> — put search, maps and collaborative editing together."},"changes":["+ Edit → WebSocket → queue","+ Transform → three stores","+ Converge → one document"],"scene":{"entities":[{"k":"p","type":"panel","x":0,"y":0,"title":"The pipeline","lines":["edit    → WebSocket → queue","transform → metadata / content / ops","converge → everyone sees the same page"]}],"links":[]}}]};
})();
